splay:flex;flex-wrap:wrap;gap:8px;width:100%}.purchase-attachment :deep(.attachment-dropzone){flex:1 1 100%}.attachment-chip{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 9px;border-radius:999px;background:#edf1e8;color:var(--dl-text-secondary);font-size:10px;font-weight:700}.attachment-chip button{width:16px;height:16px;border:0;border-radius:50%;background:#fff;color:var(--dl-danger);cursor:pointer}.upload-row{display:grid;grid-template-columns:116px minmax(0,1fr);align-items:stretch;gap:16px}.cover-preview{position:relative;min-height:116px;overflow:hidden;border:0;border-radius:18px;background:#fff}.cover-preview.empty{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:5px;border:1px dashed #d9dfd4;background:#fafbf8;color:var(--dl-text-secondary);text-align:center}.cover-preview.empty strong{font-size:12px}.cover-preview.empty small{max-width:88px;font-size:10px;line-height:1.45}.cover-preview.has-image{padding:0;cursor:zoom-in}.cover-preview.has-image img{display:block;width:100%;height:100%;object-fit:cover;transition:transform .2s ease}.cover-preview.has-image:hover img{transform:scale(1.04)}.cover-preview.has-image span{position:absolute;right:7px;bottom:7px;padding:3px 6px;border-radius:5px;background:rgba(20,29,20,.72);color:#fff;font-size:9px;opacity:0;transition:opacity .18s ease}.cover-preview.has-image:hover span,.cover-preview.has-image:focus-visible span{opacity:1}.cover-tools{display:flex;min-height:116px;flex-direction:column}.upload-row :deep(.attachment-dropzone){max-width:none}.cover-tools .cover-actions{margin-top:10px}.cover-preview-stage{display:grid;min-height:240px;max-height:70vh;place-items:center;background:conic-gradient(#f0f2ee 25%,#fff 0 50%,#f0f2ee 0 75%,#fff 0) 0/20px 20px;border-radius:14px;overflow:hidden}.cover-preview-stage img{display:block;max-width:100%;max-height:68vh;object-fit:contain}
.cover-actions{display:flex;flex-wrap:wrap;gap:9px;margin-top:10px}.cover-action-button{display:inline-flex;align-items:center;justify-content:center;gap:6px;min-height:36px;padding:0 14px;border:1px solid #d7e0cf;border-radius:10px;background:#fff;color:#3e5140;font-size:12px;font-weight:800;cursor:pointer;transition:.18s ease}.cover-action-button span{font-size:18px;line-height:1}.cover-action-button.search{border-color:#a7d64c;background:#f5ffe2;color:#3f620c}.cover-action-button.search:hover{background:#eaffba;box-shadow:0 5px 12px rgba(101,151,26,.14)}.cover-action-button.remove-bg{border-color:#d9d6ef;background:#f8f7ff;color:#5f578a}.cover-action-button.remove-bg:hover:not(:disabled){background:#efedff;box-shadow:0 5px 12px rgba(89,75,164,.13)}.cover-action-button:disabled{opacity:.48;cursor:not-allowed}.image-search-bar{display:grid;grid-template-columns:220px minmax(0,1fr) 124px;align-items:center;gap:12px}.image-search-bar :deep(.el-select),.image-search-bar :deep(.el-input),.image-search-bar :deep(.primary-button){width:100%;height:44px}.image-search-bar :deep(.el-select__wrapper),.image-search-bar :deep(.el-input__wrapper){box-sizing:border-box;min-height:44px;border-radius:12px}.image-search-bar :deep(.primary-button){min-width:0;padding:0;border-radius:12px}.image-search-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:16px}.image-search-grid button{border:1px solid #e1e4dd;border-radius:10px;background:#fff;overflow:hidden;text-align:left;cursor:pointer}.image-search-grid img{width:100%;height:105px;object-fit:cover}.image-search-grid span{display:block;padding:7px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:10px}.remove-bg-preview{display:flex;flex-direction:column;gap:14px}.remove-bg-preview p{margin:0;color:var(--dl-text-secondary);font-size:12px;line-height:1.6}.remove-bg-preview img{display:block;max-width:100%;max-height:430px;margin:0 auto;border:1px solid #e4e8df;border-radius:14px;background:conic-gradient(#f1f2ef 25%,#fff 0 50%,#f1f2ef 0 75%,#fff 0) 0/20px 20px;object-fit:contain}.remove-bg-dialog-footer{display:flex;justify-content:flex-end;align-items:center;gap:10px}.remove-bg-dialog-footer .secondary-button,.remove-bg-dialog-footer :deep(.primary-button){display:inline-flex;align-items:center;justify-content:center;width:146px;height:42px;min-height:42px;padding:0;border-radius:12px;font-size:13px;line-height:1}.remove-bg-dialog-footer .secondary-button{margin:0}
@media(max-width:760px){.dl-form>.form-grid,.purchase-grid,.purchase-bottom-grid,.image-search-bar{grid-template-columns:1fr}.purchase-row{padding:0 16px 16px}.purchase-row-heading{align-items:flex-start;flex-direction:column;margin-right:-16px;margin-left:-16px;padding:14px 16px}.record-summary{flex-wrap:wrap}.upload-row{grid-template-columns:1fr}.cover-preview{min-height:200px}.upload-row :deep(.attachment-dropzone){max-width:none}}
